def build_invoice_summary(invoice):
    if invoice is None:
        invoice = {}
    t = invoice.get('total')
    c = invoice.get('currency')
    i = invoice.get('issued_at')
    result = {'total': t, 'currency': c, 'issued_at': i}
    if not invoice:
        result['created_at'] = i
    return result
